import { EventEmitter } from 'node:events'
import type { QuickTunnel } from '../shared/model'
import type { Supervisor } from './supervisor/process'
import type { CloudflareProvider } from './providers/cloudflare'
import type { LocalCacheStore } from './cache/store'

/**
 * Regex matching TryCloudflare random domain links generated by cloudflared.
 * Example log line:
 * |  https://random-words-1234.trycloudflare.com  |
 */
const TRYCLOUDFLARE_REGEX = /https:\/\/[a-zA-Z0-9-]+\.trycloudflare\.com/i

export function normalizeTargetUrl(input: string): string {
  const trimmed = input.trim()
  if (!trimmed) return 'http://localhost:3000'
  if (/^\d+$/.test(trimmed)) {
    return `http://localhost:${trimmed}`
  }
  if (!/^https?:\/\//i.test(trimmed)) {
    return `http://${trimmed}`
  }
  return trimmed
}

const CONNECTOR_POLL_MS = 3_000
const CONNECTOR_WAIT_MS = 60_000
const NO_CONNECTOR_WAITING = 'Hostname configured; waiting for a cloudflared connector to attach to this tunnel…'
const NO_CONNECTOR_TIMEOUT =
  'Hostname is configured but no cloudflared connector is attached to this tunnel, so the edge returns 530. Start cloudflared for this tunnel, or Stop to tear the hostname down.'

export interface QuickTunnelStartOptions {
  customId?: string
  mode?: 'trycloudflare' | 'custom_domain'
  customDomain?: {
    tunnelId: string
    hostname: string
    zoneId?: string
  }
}

export class QuickTunnelManager extends EventEmitter {
  private supervisor: Supervisor
  private getCloudflare?: () => CloudflareProvider | null
  private cache?: LocalCacheStore
  private tunnels = new Map<string, QuickTunnel>()
  private startTimers = new Map<string, NodeJS.Timeout>()

  constructor(
    supervisor: Supervisor,
    getCloudflare?: () => CloudflareProvider | null,
    cache?: LocalCacheStore,
  ) {
    super()
    this.supervisor = supervisor
    this.getCloudflare = getCloudflare
    this.cache = cache

    this.loadPersisted()

    // Intercept logs to extract the generated trycloudflare.com URL or detect early errors
    this.supervisor.on('log', ({ source, line }) => {
      if (!source.startsWith('quick:')) return
      const id = source.replace(/^quick:/, '')
      const tunnel = this.tunnels.get(id)
      if (!tunnel) return

      const match = line.match(TRYCLOUDFLARE_REGEX)
      if (match && (!tunnel.publicUrl || tunnel.status !== 'running')) {
        this.clearStartTimeout(id)
        tunnel.publicUrl = match[0]
        tunnel.status = 'running'
        tunnel.error = undefined
        this.emit('update', tunnel)
        this.persist()
        return
      }

      // Check for TryCloudflare rate limiting (HTTP 429) or registration failure
      if (tunnel.status === 'starting' && !tunnel.publicUrl) {
        const lower = line.toLowerCase()
        if (line.includes('429') || lower.includes('too many requests')) {
          this.clearStartTimeout(id)
          tunnel.status = 'crashed'
          tunnel.error =
            'TryCloudflare rate limit reached (HTTP 429: Too Many Requests). Cloudflare limits free tunnels per IP. Please wait a few minutes or use a Custom Domain tunnel.'
          this.emit('update', tunnel)
          this.persist()
        } else if (
          lower.includes('failed to request quick tunnel') ||
          lower.includes('failed to create new tunnel') ||
          lower.includes('unable to create quick tunnel')
        ) {
          this.clearStartTimeout(id)
          tunnel.status = 'crashed'
          tunnel.error = `TryCloudflare initialization error: ${line.trim()}`
          this.emit('update', tunnel)
          this.persist()
        }
      }
    })

    // Intercept process state changes
    this.supervisor.on('state', ({ source, state, detail }) => {
      if (!source.startsWith('quick:')) return
      const id = source.replace(/^quick:/, '')
      const tunnel = this.tunnels.get(id)
      if (!tunnel) return

      if (state === 'crashed') {
        this.clearStartTimeout(id)
        tunnel.status = 'crashed'
        tunnel.error = detail || 'cloudflared exited unexpectedly'
        this.emit('update', tunnel)
        this.persist()
      } else if (state === 'stopped') {
        this.clearStartTimeout(id)
        tunnel.status = 'stopped'
        this.emit('update', tunnel)
        this.persist()
      } else if (state === 'running' && !tunnel.publicUrl) {
        // Still starting until publicUrl is discovered from log output
        tunnel.status = 'starting'
        this.emit('update', tunnel)
      }
    })
  }

  private sharesRoute(a: QuickTunnel, b: QuickTunnel): boolean {
    return (
      a.tunnelType === 'custom_domain' &&
      b.tunnelType === 'custom_domain' &&
      a.tunnelId === b.tunnelId &&
      a.hostname === b.hostname
    )
  }

  /** Polls the edge until a connector registers, then flips the row to running; gives up after CONNECTOR_WAIT_MS. */
  private watchForConnector(tunnel: QuickTunnel, cloudflare: CloudflareProvider): void {
    const deadline = Date.now() + CONNECTOR_WAIT_MS
    this.clearStartTimeout(tunnel.id)
    const tick = async (): Promise<void> => {
      if (this.tunnels.get(tunnel.id) !== tunnel || tunnel.status !== 'starting') return
      let connections = 0
      try {
        connections = await cloudflare.tunnelConnectionCount(tunnel.tunnelId!)
      } catch {
        // transient API error: retry until the deadline
      }
      if (this.tunnels.get(tunnel.id) !== tunnel || tunnel.status !== 'starting') return
      if (connections > 0) {
        tunnel.status = 'running'
        tunnel.error = undefined
      } else if (Date.now() >= deadline) {
        tunnel.status = 'crashed'
        tunnel.error = NO_CONNECTOR_TIMEOUT
      } else {
        this.startTimers.set(tunnel.id, setTimeout(() => void tick(), CONNECTOR_POLL_MS))
        return
      }
      this.startTimers.delete(tunnel.id)
      this.emit('update', tunnel)
      this.persist()
    }
    this.startTimers.set(tunnel.id, setTimeout(() => void tick(), CONNECTOR_POLL_MS))
  }

  private clearStartTimeout(id: string): void {
    const timer = this.startTimers.get(id)
    if (timer) {
      clearTimeout(timer)
      this.startTimers.delete(id)
    }
  }

  private loadPersisted(): void {
    if (!this.cache) return
    try {
      const raw = this.cache.getMeta('quick_tunnels')
      if (!raw) return
      const list = JSON.parse(raw) as QuickTunnel[]
      for (const t of list) {
        // If app restarted while TryCloudflare was running, process died with app
        if (t.tunnelType !== 'custom_domain' && (t.status === 'starting' || t.status === 'running')) {
          t.status = 'stopped'
        }
        if (t.tunnelType === 'custom_domain' && t.status === 'starting') {
          t.status = 'crashed'
          t.error = 'App restarted before the hostname finished starting. Stop it to tear down, then start again.'
        }
        this.tunnels.set(t.id, t)
      }
    } catch {
      // ignore
    }
  }

  private persist(): void {
    if (!this.cache) return
    try {
      this.cache.setMeta('quick_tunnels', JSON.stringify([...this.tunnels.values()]))
    } catch {
      // ignore
    }
  }

  async start(
    rawTargetUrl: string,
    options?: QuickTunnelStartOptions | string,
  ): Promise<QuickTunnel> {
    const opts: QuickTunnelStartOptions =
      typeof options === 'string' ? { customId: options } : options || {}

    const targetUrl = normalizeTargetUrl(rawTargetUrl)
    const isCustomDomain = opts.mode === 'custom_domain' && opts.customDomain

    if (isCustomDomain) {
      const { tunnelId, hostname, zoneId } = opts.customDomain!
      if (!tunnelId) throw new Error('Target tunnel ID is required for custom domain expose')
      if (!hostname) throw new Error('Hostname is required for custom domain expose')

      const cloudflare = this.getCloudflare?.()
      if (!cloudflare) {
        throw new Error('No Cloudflare account configured. Please connect your account first.')
      }

      const id = opts.customId || `qt_cd_${Date.now()}_${Math.random().toString(36).slice(2, 6)}`
      const tunnel: QuickTunnel = {
        id,
        targetUrl,
        publicUrl: `https://${hostname.toLowerCase()}`,
        status: 'starting',
        createdAt: new Date().toISOString(),
        tunnelType: 'custom_domain',
        hostname: hostname.toLowerCase(),
        tunnelId,
        zoneId,
      }
      // A hostname maps to exactly one ingress rule, so a new row for the same
      // tunnel+hostname supersedes older ones instead of coexisting with them.
      for (const other of this.tunnels.values()) {
        if (other.id !== id && this.sharesRoute(other, tunnel) && other.status !== 'stopped') {
          other.status = 'stopped'
          this.emit('update', other)
        }
      }
      this.tunnels.set(id, tunnel)
      this.emit('update', tunnel)
      this.persist()

      try {
        await cloudflare.exposeHostname({
          tunnelId,
          hostname: hostname.toLowerCase(),
          service: targetUrl,
          zoneId,
        })
        // The API call only edits config; the hostname serves traffic once a
        // cloudflared connector is attached, so wait for that before saying running.
        let connections = 0
        try {
          connections = await cloudflare.tunnelConnectionCount(tunnelId)
        } catch {
          // Unknown: treat as no connector and keep polling below.
        }
        if (connections > 0) {
          tunnel.status = 'running'
        } else {
          tunnel.error = NO_CONNECTOR_WAITING
          this.watchForConnector(tunnel, cloudflare)
        }
        this.emit('update', tunnel)
        this.persist()
        return tunnel
      } catch (err) {
        tunnel.status = 'crashed'
        tunnel.error = err instanceof Error ? err.message : String(err)
        this.emit('update', tunnel)
        this.persist()
        throw err
      }
    }

    // TryCloudflare ephemeral mode
    const id = opts.customId || `qt_${Date.now()}_${Math.random().toString(36).slice(2, 6)}`
    const procId = `quick:${id}`

    // Stop existing process if already running with this ID
    const existing = this.tunnels.get(id)
    if (existing && (existing.status === 'starting' || existing.status === 'running')) {
      return existing
    }

    const tunnel: QuickTunnel = {
      id,
      targetUrl,
      status: 'starting',
      createdAt: new Date().toISOString(),
      tunnelType: 'trycloudflare',
    }
    this.tunnels.set(id, tunnel)

    this.supervisor.spawn({
      id: procId,
      command: 'cloudflared',
      args: ['tunnel', '--url', targetUrl, '--no-autoupdate'],
      restart: false,
    })

    // Timeout after 40 seconds if TryCloudflare doesn't return a public URL
    this.clearStartTimeout(id)
    const timeoutTimer = setTimeout(() => {
      const current = this.tunnels.get(id)
      if (current && current.status === 'starting' && !current.publicUrl) {
        current.status = 'crashed'
        current.error =
          'TryCloudflare timed out after 40 seconds. Cloudflare Edge may be rate limiting this IP or the connection was blocked. Consider using Custom Domain or trying again later.'
        this.emit('update', current)
        this.persist()
        void this.supervisor.stop(procId)
      }
    }, 40_000)
    this.startTimers.set(id, timeoutTimer)

    this.emit('update', tunnel)
    this.persist()
    return tunnel
  }

  async stop(id: string): Promise<boolean> {
    this.clearStartTimeout(id)
    const tunnel = this.tunnels.get(id)
    if (!tunnel) return false

    if (tunnel.tunnelType === 'custom_domain' && tunnel.tunnelId && tunnel.hostname) {
      const routeInUse = [...this.tunnels.values()].some(
        (t) =>
          t.id !== id &&
          (t.status === 'starting' || t.status === 'running') &&
          this.sharesRoute(t, tunnel),
      )
      const cloudflare = this.getCloudflare?.()
      if (cloudflare && !routeInUse) {
        try {
          await cloudflare.unexposeHostname({
            tunnelId: tunnel.tunnelId,
            hostname: tunnel.hostname,
            zoneId: tunnel.zoneId,
            deleteDns: true,
          })
        } catch (err) {
          tunnel.error = `Teardown failed, hostname may still be configured: ${
            err instanceof Error ? err.message : String(err)
          }`
          this.emit('update', tunnel)
          this.persist()
          throw err
        }
      }
      tunnel.status = 'stopped'
      tunnel.error = undefined
      this.emit('update', tunnel)
      this.persist()
      return true
    }

    const procId = `quick:${id}`
    const stopped = await this.supervisor.stop(procId)
    tunnel.status = 'stopped'
    this.emit('update', tunnel)
    this.persist()
    return stopped
  }

  list(): QuickTunnel[] {
    return [...this.tunnels.values()]
  }

  get(id: string): QuickTunnel | undefined {
    return this.tunnels.get(id)
  }
}
